class App:
    def __init__(self, root):
        self.root = root
        root.title("sellfox-bridge · 启动器")

    def handle(self, key):
        # pythonw 无控制台：未捕获异常 = 点击完全没反应，必须弹框
        try:
            self._handle(key)
        except Exception as e:
            messagebox.showerror("启动失败", f"{key}\n\n{type(e).__name__}: {e}")
